package nl.smartstreamlabs.sbwdroneconfig;
import java.util.*;import net.minecraft.core.BlockPos;import net.minecraft.network.FriendlyByteBuf;import net.minecraft.network.chat.Component;import net.minecraft.server.level.ServerPlayer;import net.minecraft.world.*;import net.minecraft.world.entity.player.*;import net.minecraft.world.inventory.*;import net.minecraft.world.item.ItemStack;
/** Display slots are never inventories. Every bulk gesture is validated against
 * the exact server page revision, then translated to bounded physical stacks. */
public final class DwfMenu extends AbstractContainerMenu{
 public final BlockPos root;public final int chest;public DwfReply view;private final Inventory inventory;private final DwfBlockEntity block;private final DwfMachine machine;private final SimpleContainer icons=new SimpleContainer(27);private final List<DwfItemKey>keys=new ArrayList<>();private final List<String>recipes=new ArrayList<>();private final ArrayDeque<DwfAction>actions=new ArrayDeque<>();
 private final Set<Integer>drag=new LinkedHashSet<>();private int dragMode=-1,dragState,clientDragState;private long dragRevision=-1,clientDragRevision;private ItemStack dragCarried=ItemStack.EMPTY;private boolean clientDragging;private String search="";private int page,sort;private long revision,seen=-1,nextRefresh,lastProgress;private DwfWorkBudget.Job searchJob;private boolean closed;private final DwfWorkBudget.Job transport=new DwfWorkBudget.Job(){public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.TRANSPORT;}public boolean step(){var action=actions.poll();if(action!=null&&!closed&&stillValid(inventory.player))apply(action);return !actions.isEmpty();}};
 public DwfMenu(int id,Inventory inventory,FriendlyByteBuf buf){this(id,inventory,buf.readBlockPos(),buf.readVarInt(),null);}
 private DwfMenu(int id,Inventory inventory,BlockPos root,int chest,DwfBlockEntity block){super(AddonMenus.DWF01.get(),id);this.inventory=inventory;this.root=root;this.chest=chest;this.block=block;machine=block==null?null:block.machine();for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(icons,r*9+c,8+c*18,51+r*18){public boolean mayPlace(ItemStack s){return inventory.player.level().isClientSide;}public boolean mayPickup(Player p){return p.level().isClientSide;}});for(int r=0;r<3;r++)for(int c=0;c<9;c++)addSlot(new Slot(inventory,r*9+c+9,8+c*18,151+r*18));for(int c=0;c<9;c++)addSlot(new Slot(inventory,c,8+c*18,209));if(block!=null){if(chest==0)block.inputViewers++;else if(chest==1)block.outputViewers++;block.visualChanged();query();}}
 public static void open(ServerPlayer p,DwfBlockEntity b,int chest){p.openMenu(new SimpleMenuProvider((id,inv,player)->new DwfMenu(id,inv,b.getBlockPos(),chest,b),Component.literal(chest==0?"DWF-01 | Materials":chest==1?"DWF-01 | Output":"DWF-01 | Fabrication")),buf->{buf.writeBlockPos(b.getBlockPos());buf.writeVarInt(chest);});}
 private DwfServer.Context context(){return machine.serverContext();}
 public void request(DwfAction m){if(inventory.player.isSpectator()&&(m.action()<1||m.action()>3))return;if(actions.size()<64){actions.add(m);context().work.add(transport);}}
 public void send(int action,int slot,int button,int type,String text){AddonNetwork.dwfAction(new DwfAction(containerId,getStateId(),action,slot,button,type,view==null?0:view.revision(),text));}
 private void apply(DwfAction m){try{switch(m.action()){
  case 0->{if(m.gesture()==ClickType.QUICK_CRAFT.ordinal()){quickCraft(m);}else{clearDrag();if(m.revision()!=revision||m.stateId()!=getStateId()){broadcastFullState();return;}gesture(m.slot(),m.button(),m.gesture());}}
  case 1->{clearDrag();search=m.text().trim().toLowerCase(Locale.ROOT);page=0;query();}
  case 2->{clearDrag();int total=chest<2?machine.storage(chest).counts.size():context().catalog().entries().size();int last=Math.max(0,(total+26)/27-1);page=Math.max(0,Math.min(last,m.slot()));query();}
  case 3->{clearDrag();sort=Math.floorMod(m.slot(),3);page=0;query();}
  case 4->{if(chest==2&&m.revision()==revision&&m.stateId()==getStateId()&&m.slot()>=0&&m.slot()<recipes.size()){machine.select(recipes.get(m.slot()));query();}}
  case 5->{if(chest==2){long batch=Long.parseLong(m.text());if(batch<1||batch>1_000_000)throw new IllegalArgumentException();machine.start(batch,m.button()==1,(ServerPlayer)inventory.player);}}
  case 6->{if(chest==2&&m.slot()>=1&&m.slot()<=3)machine.action(m.slot());}
  default->{} }
 }catch(RuntimeException failure){inventory.player.displayClientMessage(Component.literal("DWF-01: action unavailable"),true);}broadcastChanges();}
 private void query(){if(closed)return;if(searchJob!=null)context().work.remove(searchJob);final long expected=machine.revision();final var found=new ArrayList<DwfItemKey>();final var foundRecipes=new ArrayList<String>();final var stacks=new ArrayList<ItemStack>();final var counts=new ArrayList<Long>();final int offset=page*27;var cursor=chest<2?machine.storage(chest).index.search(DwfIndex.Sort.values()[sort]):null;var catalog=chest==2?context().catalogOrder(sort).iterator():null;
  searchJob=new DwfWorkBudget.Job(){int matched;boolean more;public DwfWorkBudget.Kind kind(){return DwfWorkBudget.Kind.INDEX;}public boolean step(){if(closed)return false;int work=0;while(work++<256&&(chest<2?cursor.hasNext():catalog.hasNext())){if(chest<2){var row=cursor.next();if(!row.search().contains(search))continue;if(matched++<offset)continue;if(stacks.size()==27){more=true;break;}found.add(row.key());foundRecipes.add("");stacks.add(row.key().stack(1));counts.add(row.count());}else{var recipe=catalog.next();if(!(recipe.output().getHoverName().getString()+" "+recipe.category()+" "+recipe.id()).toLowerCase(Locale.ROOT).contains(search))continue;if(matched++<offset)continue;if(stacks.size()==27){more=true;break;}foundRecipes.add(recipe.id().toString());stacks.add(recipe.product());counts.add((long)recipe.output().getCount());}}if(!more&&(chest<2?cursor.hasNext():catalog.hasNext()))return true;keys.clear();keys.addAll(found);recipes.clear();recipes.addAll(foundRecipes);for(int i=0;i<27;i++)icons.setItem(i,i<stacks.size()?stacks.get(i):ItemStack.EMPTY);revision++;seen=expected;searchJob=null;sendView(counts,more);return false;}};context().work.add(searchJob);
 }
 private void sendView(List<Long>counts,boolean more){var store=machine.storage(chest==1?1:0).counts;var r=machine.production.recipe();var details=new ArrayList<String>();var materials=new ArrayList<DwfReply.Material>();if(machine.selected()!=null)for(var need:machine.selected().inputs()){var choices=need.ingredient().getItems();var icon=choices.length==0?ItemStack.EMPTY:choices[0];materials.add(new DwfReply.Material(icon,choices.length==0?"Unavailable ingredient":icon.getHoverName().getString(),machine.input.available(need.ingredient()),need.count()));}String status=machine.error().isEmpty()?machine.presentationState():machine.error();long now=inventory.player.level().getGameTime();long progress=machine.production.progress();if(view!=null&&now-lastProgress<10)progress=view.progress();else lastProgress=now;var reply=new DwfReply(containerId,revision,page,more,store.total(),store.capacity(),store.size(),store.variantLimit(),status,progress,r==null?machine.selected()==null?1:machine.productionTicks():r.ticks(),machine.selected()==null?"Select a product":machine.selected().output().getHoverName().getString()+" ("+machine.selected().category()+")",machine.order().remaining(),machine.order().continuous(),machine.creativeMode(),counts,new ArrayList<>(recipes),details,materials);if(!reply.equals(view)){AddonNetwork.dwfReply((ServerPlayer)inventory.player,reply);view=reply;}super.broadcastChanges();}
 @Override public void broadcastChanges(){if(block!=null&&!closed){long now=inventory.player.level().getGameTime();if(now>=nextRefresh){nextRefresh=now+4;if(searchJob==null&&(seen!=machine.revision()||view==null))query();else if(view!=null)sendView(view.counts(),view.more());}}super.broadcastChanges();}
 @Override public void clicked(int slot,int button,ClickType type,Player player){
  if(chest==2&&type==ClickType.QUICK_CRAFT){super.clicked(slot,button,type,player);return;}
  if(slot<27&&slot>=0||type==ClickType.QUICK_CRAFT){if(player.level().isClientSide){
   if(type==ClickType.QUICK_CRAFT){int event=getQuickcraftHeader(button);if(event==0){clientDragging=true;clientDragRevision=view==null?0:view.revision();clientDragState=getStateId();}if(clientDragging)AddonNetwork.dwfAction(new DwfAction(containerId,clientDragState,0,slot,button,type.ordinal(),clientDragRevision,""));if(event>=2)clientDragging=false;}
   else{clientDragging=false;send(0,slot,button,type.ordinal(),"");}
  }return;}
  if(!player.level().isClientSide)clearDrag();else clientDragging=false;super.clicked(slot,button,type,player);
 }
 private void clearDrag(){drag.clear();dragMode=-1;dragRevision=-1;dragCarried=ItemStack.EMPTY;}
 /** Deposits use the server-owned cursor, not an item selected from a page.
  * Freeze one gesture token while asynchronous count/page updates continue. */
 private void quickCraft(DwfAction action){
  if(chest==2)return;int event=getQuickcraftHeader(action.button()),mode=getQuickcraftType(action.button());
  if(event==0){clearDrag();if(mode<2&&!getCarried().isEmpty()){dragMode=mode;dragRevision=action.revision();dragState=action.stateId();dragCarried=getCarried().copy();}return;}
  if(dragMode<0||action.revision()!=dragRevision||action.stateId()!=dragState||getCarried().getCount()!=dragCarried.getCount()||!ItemStack.isSameItemSameComponents(getCarried(),dragCarried)){clearDrag();return;}
  int slot=action.slot();if(event==1&&slot>=0&&slot<slots.size()){if(slot<27)drag.add(slot);else{var target=slots.get(slot);var there=target.getItem();if(target.mayPlace(getCarried())&&(there.isEmpty()||ItemStack.isSameItemSameComponents(there,getCarried()))&&there.getCount()<target.getMaxStackSize(getCarried()))drag.add(slot);}}
  else if(event==2){int amount=dragMode==1?1:drag.isEmpty()?0:getCarried().getCount()/drag.size();for(int target:drag)deposit(target,amount);clearDrag();}
 }
 private void gesture(int slot,int button,int type){if(type<0||type>=ClickType.values().length||chest==2)return;var click=ClickType.values()[type];if(slot>=0&&slot<27&&click==ClickType.PICKUP&&!getCarried().isEmpty()){deposit(slot,button==1?1:getCarried().getCount());return;}if(slot<0||slot>=keys.size())return;var key=keys.get(slot);var store=machine.storage(chest);if(click==ClickType.QUICK_MOVE){var stack=store.extractStack(key,key.maxStackSize(),false);if(!stack.isEmpty()){moveItemStackTo(stack,27,63,true);if(!stack.isEmpty())store.insert(stack,stack.getCount(),false);}return;}if(click!=ClickType.PICKUP||button<0||button>1)return;if(!getCarried().isEmpty()){deposit(slot,button==1?1:getCarried().getCount());return;}long available=store.counts.count(key);int take=(int)Math.min(key.maxStackSize(),available);if(button==1)take=(take+1)/2;setCarried(store.extractStack(key,take,false));}
 private void deposit(int slot,int amount){if(amount<1||getCarried().isEmpty())return;var carried=getCarried();amount=Math.min(amount,carried.getCount());if(slot<27){long inserted=machine.storage(chest).insert(carried,amount,false);carried.shrink((int)inserted);}else if(slot<slots.size()){var target=slots.get(slot);var there=target.getItem();if(target.mayPlace(carried)&&(there.isEmpty()||ItemStack.isSameItemSameComponents(there,carried))){int take=Math.min(amount,target.getMaxStackSize(carried)-there.getCount());if(take>0){if(there.isEmpty())target.set(carried.split(take));else{there.grow(take);carried.shrink(take);target.setChanged();}}}}}
 @Override public ItemStack quickMoveStack(Player player,int slot){if(machine==null||chest==2||slot<27||slot>=slots.size())return ItemStack.EMPTY;var source=slots.get(slot);var original=source.getItem().copy();var stack=source.getItem();long inserted=machine.storage(chest).insert(stack,stack.getCount(),false);stack.shrink((int)inserted);source.setChanged();return inserted==0?ItemStack.EMPTY:original;}
 @Override public boolean stillValid(Player player){return block==null?true:machine.ready()&&!block.isRemoved()&&block.allowed(player);}
 @Override public void removed(Player player){closed=true;if(block!=null){context().work.remove(transport);if(searchJob!=null)context().work.remove(searchJob);if(chest==0)block.inputViewers=Math.max(0,block.inputViewers-1);else if(chest==1)block.outputViewers=Math.max(0,block.outputViewers-1);block.visualChanged();}super.removed(player);}
}
